190|     @Test public void preservesSpaceInScript() {
191|         // preserve because it's content is a data node
192|         Document doc = Jsoup.parse("<script>\nOne\n\tTwo\n\tThree\n</script>");
193|         String expect = "\nOne\n\tTwo\n\tThree\n";
194|         Element el = doc.select("script").first();
195|         assertEquals(expect, el.data());
196|         assertEquals("One\n\tTwo\n\tThree", el.html());
197|         assertEquals("<script>" + expect + "</script>", el.outerHtml());
198|     }
